-- PRODUCTION READ-ONLY INVENTORY: lqvuqamzmchepgxkftcw.
-- Independently verify Dashboard/connection endpoint; this comment is not identity proof.
-- No schema installation, role changes, maintenance locks or feature activation.
begin transaction isolation level repeatable read read only;
set local statement_timeout='20s';
set local lock_timeout='2s';
select jsonb_build_object(
'observedAt',clock_timestamp(),'database',current_database(),'role',current_user,'readOnly',current_setting('transaction_read_only'),'version',version(),'serverVersionNum',current_setting('server_version_num'),'recovery',pg_is_in_recovery(),
'ledger',(select jsonb_agg(jsonb_build_object('version',version,'name',name,'statementCount',cardinality(statements),'firstSourceBytes',octet_length(statements[1]),'firstSourceSha256',case when statements[1] is not null then encode(sha256(convert_to(replace(statements[1],chr(13),''),'UTF8')),'hex') end,'joinedSourceSha256',case when cardinality(statements)>0 then encode(sha256(convert_to(replace(array_to_string(statements,E'\n'),chr(13),''),'UTF8')),'hex') end) order by version) from supabase_migrations.schema_migrations),
'tables',(select jsonb_agg(jsonb_build_object('name',n.nspname||'.'||c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl,'replident',c.relreplident) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','app_private','storage') and c.relkind in('r','p','v','m','S')),
'columns',(select jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in('public','app_private','storage') and c.relkind in('r','p') and a.attnum>0 and not a.attisdropped),
'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'oid',p.oid,'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,'securityDefiner',p.prosecdef,'config',p.proconfig,'volatility',p.provolatile,'bodySha256',encode(sha256(convert_to(replace(p.prosrc,chr(13),''),'UTF8')),'hex'),'definitionSha256',encode(sha256(convert_to(replace(pg_get_functiondef(p.oid),chr(13),''),'UTF8')),'hex'),'custom40001Points',(length(p.prosrc)-length(replace(p.prosrc,'''40001''','')))/7,'pt409Points',(length(p.prosrc)-length(replace(p.prosrc,'''PT409''','')))/7) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','app_private') and p.prokind in('f','p')),
'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in('public','app_private','storage')),
'triggers',(select jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text) order by t.tgrelid::regclass::text,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in('public','app_private','storage')),
'constraints',(select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated) order by c.conrelid::regclass::text,c.conname) from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname in('public','app_private','storage')),
'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) order by nspname) from pg_namespace where nspname in('public','app_private','storage','auth','supabase_migrations')),
'roles',(select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'createRole',rolcreaterole,'createDb',rolcreatedb,'canLogin',rolcanlogin,'bypassRls',rolbypassrls) order by rolname) from pg_roles),
'roleMemberships',(select jsonb_agg(jsonb_build_object('role',r.rolname,'member',u.rolname,'options',to_jsonb(m)-'roleid'-'member'-'grantor') order by r.rolname,u.rolname) from pg_auth_members m join pg_roles r on r.oid=m.roleid join pg_roles u on u.oid=m.member),
'publications',(select jsonb_agg(to_jsonb(p) order by pubname) from pg_publication p),
'publicationTables',(select jsonb_agg(to_jsonb(p) order by pubname,schemaname,tablename) from pg_publication_tables p),
'extensions',(select jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace),
'permissions',jsonb_build_object('databaseCreate',has_database_privilege(current_user,current_database(),'CREATE'),'schemaPublicCreate',has_schema_privilege(current_user,'public','CREATE'),'schemaPrivateCreate',has_schema_privilege(current_user,'app_private','CREATE'),'authUsersSelect',has_table_privilege(current_user,'auth.users','SELECT'),'storageObjectsSelect',has_table_privilege(current_user,'storage.objects','SELECT'))
) inventory;
commit;
